window.currentLang = localStorage.getItem('fitplan_lang') || 'hu';

window.t = function(key) {
    const lang = window.currentLang;
    if (window.i18nData[lang] && window.i18nData[lang][key]) return window.i18nData[lang][key];
    return (window.i18nData['hu'] && window.i18nData['hu'][key]) ? window.i18nData['hu'][key] : key;
};

window.applyTranslations = function() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        const trans = window.t(key);
        if (trans) {
            if (el.tagName === 'INPUT' && el.getAttribute('placeholder')) el.placeholder = trans;
            else el.textContent = trans;
        }
    });

    ['hu', 'en', 'de', 'fr', 'es', 'zh'].forEach(code => {
        const check = document.getElementById(`lang-check-${code}`);
        if (check) check.classList.toggle('hidden', code !== window.currentLang);
    });

    if (typeof window.renderAllActiveViews === 'function') window.renderAllActiveViews();
};

window.changeLanguage = function(lang) {
    window.currentLang = lang;
    localStorage.setItem('fitplan_lang', lang);
    window.applyTranslations();
    if (typeof window.closeModal === 'function') window.closeModal('settings-modal');
    if (typeof window.showToast === 'function') window.showToast(`Nyelv: ${lang.toUpperCase()}`, 'fa-language', 'brand');
};

window.getDaysArray = function() {
    return (window.i18nData[window.currentLang] && window.i18nData[window.currentLang].days) 
        ? window.i18nData[window.currentLang].days 
        : window.i18nData['hu'].days;
};

window.getSlotNames = function() {
    return (window.i18nData[window.currentLang] && window.i18nData[window.currentLang].slots)
        ? window.i18nData[window.currentLang].slots
        : window.i18nData['hu'].slots;
};